function parseSqlValues(valuesStr) {
  const values = [];
  let current = '';
  let inQuote = false;
  let escapeNext = false;

  for (let i = 0; i < valuesStr.length; i++) {
    const char = valuesStr[i];
    if (escapeNext) {
      current += char;
      escapeNext = false;
      continue;
    }
    if (char === '\\') {
      escapeNext = true;
      continue;
    }
    if (char === "'") {
      if (inQuote && valuesStr[i + 1] === "'") {
        current += "'";
        i++;
        continue;
      }
      inQuote = !inQuote;
      continue;
    }
    if (char === ',' && !inQuote) {
      values.push(current.trim());
      current = '';
      continue;
    }
    current += char;
  }
  values.push(current.trim());
  return values;
}

function parseSqlStudent(sqlLine) {
  const openParen = sqlLine.indexOf('VALUES (');
  if (openParen === -1) return null;
  const valuesStr = sqlLine.slice(openParen + 8, sqlLine.lastIndexOf(')'));
  const vals = parseSqlValues(valuesStr);
  if (vals.length < 22) return null;

  return {
    id: vals[0],
    username: vals[1],
    studentId: vals[1],
    name: vals[2],
    gender: vals[3],
    department: vals[4],
    program: vals[5],
    residencyStatus: vals[6],
    specialization: vals[7],
    year: vals[8],
    universityEmail: vals[9],
    personalEmail: vals[10],
    mobileNumber: vals[11],
    parentName: vals[12],
    parentPhoneNumber: vals[13],
    dateOfBirth: vals[14],
    passwordHash: vals[15],
    cluster: vals[16],
    aadhaarNumber: '1234 5678 9012',
    aapaarNumber: 'APAAR-9876-5432',
    counselor: {
      employeeId: vals[17],
      name: vals[18],
      designation: vals[19],
      mobileNumber: vals[20],
      email: vals[21],
    },
  };
}

let cachedStudents = null;
let cachedStudentsMap = null;

function initializeFromSql() {
  if (cachedStudents && cachedStudentsMap) return;
  const list = [];
  const map = new Map();
  const lines = RAW_STUDENTS_SQL.trim().split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line.startsWith('INSERT INTO students')) continue;
    const student = parseSqlStudent(line);
    if (student) {
      list.push(student);
      map.set(student.username, student);
    }
  }

  cachedStudents = list;
  cachedStudentsMap = map;
}

export function getAllStudents() {
  initializeFromSql();
  return cachedStudents;
}

export function findStudentById(studentId) {
  if (!studentId) return null;
  initializeFromSql();
  return cachedStudentsMap.get(studentId) || null;
}
